pages/custom/category/category-nofilters:
---
category:
    shop_by_price: true
    products:
        limit: {{theme_settings.categorypage_products_per_page}}
---
{{inject "categoryProductsPerPage" theme_settings.categorypage_products_per_page}}
{{#partial "head"}}
    {{#if pagination.category.previous}}
        <link rel="prev" href="{{pagination.category.previous}}">
    {{/if}}
    {{#if pagination.category.next}}
        <link rel="next" href="{{pagination.category.next}}">
    {{/if}}
{{/partial}}

{{#partial "page"}}


<div class="page">
    <main class="page-content category no-filters" id="product-listing-container">
        <section class="page-content container">
            {{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}
        </section>
        <div class="container description">
            {{{region name="category_below_header"}}}
            {{{category.description}}}
            {{{snippet 'categories'}}}
        </div>

        <div class="grid-bg">
            <div class="container">
                {{#or theme_settings.subcategories_left_column theme_settings.shop_by_price_visibility}}
                    {{#if template '!==' 'pages/custom/category/category-nofilters'}}
                        <aside class="page-sidebar" id="faceted-search-container">
                            {{> components/category/sidebar}}
                        </aside>
                    {{/if}}
                {{/or}}
                <main class="page-content">
                    {{#if category.products}}
                        {{> components/category/product-listing}}
                    {{else}}
                        <div class="container">
                            <p>{{lang 'categories.no_products'}}</p>
                        </div>
                    {{/if}}
                    {{{region name="category_below_content"}}}
                </main>
            </div>
        </div>
    </main>
</div>

{{/partial}}
{{> layout/base}}

components/category/product-listing:
{{inject 'noCompareMessage' (lang 'compare.no_compare')}}

{{assignVar "category_name" category.name}}

<script type="application/ld+json">
    {
        "@context": "https://schema.org",
        "@type": "ItemList",
        "itemListElement": [
            {{#each category.products}}
            {
                "@type": "ListItem",
                "position": {{add @index 1}},
                "item": {
                    "@type": "Product",
                    "name": "{{this.name}}",
                    "image": "{{getImage this.image 'productgallery_size' (cdn theme_settings.default_image_product)}}",
                    {{#if this.summary}}"description": "{{encodeURI (sanitize this.summary)}}",{{/if}}
                    {{#if this.brand}}
                    "brand": {
                        "@type": "Brand",
                        "name": "{{this.brand.name}}"
                    },
                    {{/if}}
                    {{#if this.sku}}"sku": "{{this.sku}}",{{/if}}
                    "category": "{{getVar "category_name"}}",
                    "offers": {
                        "@type": "Offer",
                        {{#if this.price.price_range}}
                        "minPrice": "{{#if this.price.price_range.min.with_tax}}{{this.price.price_range.min.with_tax.value}}{{else}}{{this.price.price_range.min.without_tax.value}}{{/if}}",
                        "maxPrice": "{{#if this.price.price_range.max.with_tax}}{{this.price.price_range.max.with_tax.value}}{{else}}{{this.price.price_range.max.without_tax.value}}{{/if}}",
                        {{else}}
                        "price": "{{#if this.price.with_tax}}{{this.price.with_tax.value}}{{else}}{{this.price.without_tax.value}}{{/if}}",
                        {{/if}}
                        "priceCurrency": "{{this.price.with_tax.currency}}",
                        "availability": "https://schema.org/{{#if this.pre_order}}PreOrder{{else if this.stock_level '>' 0 }}InStock{{else if this.out_of_stock_message '===' undefined}}InStock{{else}}OutOfStock{{/if}}",
                        "url": "{{this.url}}"
                    }
                    {{#if this.num_reviews '>' 0}}
                    ,
                    "aggregateRating": {
                        "@type": "AggregateRating",
                        "ratingValue": "{{this.rating}}",
                        "reviewCount": "{{this.num_reviews}}"
                    }
                    {{/if}}
                }
            }{{#unless @last}},{{/unless}}
            {{/each}}
        ]
    }
</script>

{{#if category.products}}
    <div class="sort-and-pagination">
        <div class="sidebar-nav-mobile">
            {{#if category.subcategories}}
                    <a href="#subcategoryList" role="button" class="{{#if category.faceted_search_enabled}}facetedSearch-toggle{{/if}} toggleLink toggleSidebarBlock button" data-collapsible>
                        <span class="facetedSearch-toggle-indicator">
                            <span class="toggleLink-text toggleLink-text--on">
                                <i class="icon" aria-hidden="true">
                                    <svg><use xlink:href="#icon-close"></use></svg>
                                </i>
                                <span>Close to View Results</span>
                            </span>
                            <span class="toggleLink-text toggleLink-text--off">
                                <span>
                                    <i class="icon" aria-hidden="true">
